import{z as n,x as s,o as B,c as d,q as t,j as r,D as e,d as l,s as o,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"内核基准测试方法论","description":"","frontmatter":{"title":"内核基准测试方法论","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ak-benchmark-methodology.md","filePath":"llm/ak-benchmark-methodology.md","lastUpdated":1791063341000}'),m={name:"llm/ak-benchmark-methodology.md"};function p(h,a,D,C,u,c){const A=s("Mermaid");return B(),d("div",null,[a[2]||(a[2]=t('<h1 id="内核基准测试方法论" tabindex="-1">内核基准测试方法论 <a class="header-anchor" href="#内核基准测试方法论" aria-label="Permalink to &quot;内核基准测试方法论&quot;">​</a></h1><div class="epigraph"><p>测不准的内核优化是轶事：先钉死计时器、存储状态与形状网格，再谈快了多少。</p><footer>—— 据 Williams et al., Roofline, 2009；CUDA 计时与剖析工具文档整理</footer></div><p><a href="/llm/ak-longsequence-kernels">上一课</a>把长序列的并行度排满，工程化单元过半。本课立规矩：内核基准测试方法论。它不是工程化的一件杂务，而是后面调优与移植的地基——那两课的每一张配置表、每一个跨后端的倍数，都是从这套规矩里读出来的数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内核成绩单最容易在三处失真，而且多半是无意的。其一，计时含了冷启动：首次调用带着 JIT 编译、指令加载与页分配，把它算进均值，「优化」可能只是第二次跑 warmed-up 的代码。其二，存储状态失真：反复测同一组小张量，K、V 常驻 L2，带宽读数虚高，能「优化」出超过 HBM 物理上限的加速比——账面上赚，部署后赔。其三，形状抽样失真：只测一个甜点形状（比如 batch=8、\\(n=4096\\) 的方阵前填），而部署里真正占时间的解码 \\(n_q=1\\)、变长、分页形状一个都不在成绩单上。缺口是：一套让数字可信、可复现、可对比的测量协议。</p><p><span class="marginnote">术语翻译：L2 是芯片上容量小但极快的缓存（A100 约 40 MiB），HBM 是显存、容量大却慢一个量级。数据第一次从 HBM 读进 L2 后，再读就是近水楼台。基准若反复用同一小块数据，测到的就是「近水楼台」的速度——而部署时每次都要跑远路。</span></p><h3 id="三个失真一个对策" tabindex="-1">三个失真一个对策 <a class="header-anchor" href="#三个失真一个对策" aria-label="Permalink to &quot;三个失真一个对策&quot;">​</a></h3><p>冷启动、L2 驻留、形状偏样本，共同点是都让被测系统偏离部署时的真实状态。对策因此统一：让每次测量都从部署会经历的状态起步——编译已完成、缓存已冲刷、形状覆盖生产分布。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四步协议。第一，计时用设备侧事件或核时长统计，不用墙钟；剖析器只在归因时开，测量时关——开着剖析器测时间是串行化测量，数字整体偏大。第二，稳态：若干次 warmup 丢弃，再取中位数与分位数；只报均值会被长尾刷分，报散布才知道数字的信用。第三，存储状态：轮转缓冲区或显式冲刷 L2，让每次测量都从 HBM 起步；除非你要测的就是 L2 命中场景，那要作为独立场景声明。第四，形状网格：在（batch、\\(h_q\\)、\\(h_{kv}\\)、\\(n_q\\)、\\(n_{kv}\\)、\\(d\\)、dtype、布局、因果与否、连续或分页）上抽样，每格配数值验收——与参考实现比容差，容差按 dtype 与归约顺序定：归并顺序不同就不能要求逐位相同（第 7 课的分块、第 10 课的切段都换了顺序），但统计上不得有漂移。</p><p><span class="marginnote">常见误区：把第一次运行也算进平均——那一次带着「现场编译内核」的开销，可能比稳态慢几十倍；或者只报平均值，被个别长尾拖歪。规矩是先空跑几次热身再开始计时，并且报告中位数与分位数，让读者看到数字的散布有多大。</span></p>',11)),(B(),r(i,null,{default:e(()=>[o(A,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%BD%A2%E7%8A%B6%E7%BD%91%E6%A0%BC%E6%8A%BD%E6%A0%B7%22%5D%20--%3E%20B%5B%22warmup%20%E4%B8%A2%E5%BC%83%E5%86%B7%E5%90%AF%E5%8A%A8%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%86%B2%E5%88%B7%20L2%20%2F%20%E8%BD%AE%E8%BD%AC%E7%BC%93%E5%86%B2%22%5D%0A%20%20C%20--%3E%20D%5B%22%E8%AE%BE%E5%A4%87%E4%BE%A7%E8%AE%A1%E6%97%B6%EF%BC%9A%E4%B8%AD%E4%BD%8D%E6%95%B0%20%2B%20%E5%88%86%E4%BD%8D%E6%95%B0%22%5D%0A%20%20D%20--%3E%20E%5B%22%E6%95%B0%E5%80%BC%E9%AA%8C%E6%94%B6%EF%BC%9A%E5%AE%B9%E5%B7%AE%E6%8C%89%20dtype%20%E5%AE%9A%22%5D%0A%20%20E%20--%3E%20F%5B%22%E6%8A%A5%E6%9B%B2%E7%BA%BF%20%2B%20%E7%AB%AF%E5%88%B0%E7%AB%AF%E6%8A%98%E7%AE%97%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"为什么 L2 是第一大坑，算一笔就明白：\\(n=4096\\)、\\(d=128\\)、fp16 时单层 8 个 KV 头的 K+V 只有 \\(16\\,\\mathrm{MiB}\\)，A100 的 \\(40\\,\\mathrm{MiB}\\) L2 装得下两层多——不冲刷，测的就全是 L2 而不是 HBM，第一单元的带宽账整个失效。为什么必须端到端折算：内核占推理步三成时间，再省一半也只值一成五；Amdahl 定律要落到服务指标上才是结论，内核层报时间、系统层报占比，两层各归各。错法对照：用框架级端到端延迟评内核，噪声盖过差异，比了个寂寞；用均值挑配置，被一次长尾拖进错误的赢家；换卡不锁频率，同一个内核在两张表上名次不同，还以为是移植引入的回归。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"数字实例：某内核占整个推理步 30% 的时间，把它优化快一倍（省 15%），端到端也只快 15%；若它本来只占 5%，优化到零也只快 5%。所以「内核快了 2 倍」必须折算成「服务快了百分之几」才有意义——这就是 Amdahl 定律的用法。")],-1)),(B(),r(i,null,{default:e(()=>[o(A,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%8F%8D%E5%A4%8D%E6%B5%8B%E5%90%8C%E4%B8%80%E7%BB%84%E5%B0%8F%E5%BC%A0%E9%87%8F%22%5D%20--%3E%20L2%5B%22K%2CV%20%E9%A9%BB%E7%95%99%E5%9C%A8%2040%20MiB%20%E7%9A%84%20L2%20%E9%87%8C%22%5D%0A%20%20L2%20--%3E%20FAST%5B%22%E8%AF%BB%E6%95%B0%E8%B5%B0%20L2%20%E5%B8%A6%E5%AE%BD%2C%20%E8%BF%9C%E9%AB%98%E4%BA%8E%20HBM%22%5D%0A%20%20FAST%20--%3E%20PAPER%5B%22%E6%8A%A5%E5%91%8A%E5%87%BA%E8%B6%85%E8%BF%87%20HBM%20%E4%B8%8A%E9%99%90%E7%9A%84%E5%8A%A0%E9%80%9F%E6%AF%94%22%5D%0A%20%20DEP%5B%22%E9%83%A8%E7%BD%B2%E5%90%8E%E6%AF%8F%E6%AC%A1%E9%83%BD%E8%A6%81%E4%BB%8E%20HBM%20%E8%AF%BB%22%5D%20--%3E%20SLOW%5B%22%E7%9C%9F%E5%AE%9E%E6%94%B6%E7%9B%8A%E8%BF%9C%E5%B0%8F%E4%BA%8E%E8%B4%A6%E9%9D%A2%22%5D%0A%20%20FIX%5B%22%E5%86%B2%E5%88%B7%20L2%20%2F%20%E8%BD%AE%E8%BD%AC%E7%BC%93%E5%86%B2%E5%8C%BA%22%5D%20--%3E%20OK%5B%22%E6%B5%8B%E5%88%B0%E7%9A%84%E6%89%8D%E6%98%AF%20HBM%20%E9%80%9F%E5%BA%A6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">数值验收的容差不是越严越好：fp16 参考下要求 \\(10^{-3}\\) 相对误差会把正确的分块实现全判死——归约顺序换了舍入就换。口径是「与 FP32 参考比、按 dtype 分级」，而不是「与上一个实现逐位比」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>微基准不代表服务：调度开销、内核选择、批处理交互都在内核之外，系统级问题由服务课程的压测接手。低精度内核的容差更宽，但验收步骤一步不少（第 8 课的口径在这里执行）。跨设备的对比还要锁频率与功耗、统一形状与版本——那是多后端一课的验收合同。本课只立内核层的规矩：计时、稳态、存储状态、形状网格、数值验收，五件套齐了，数字才有资格进配置表。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>计时用设备侧事件、关剖析器；warmup 丢冷启动，报中位数与分位数。</li><li>不冲刷 L2 的内核基准是假的：\\(16\\,\\mathrm{MiB}\\) 的 KV 正好埋进 L2，带宽读数全部虚高。</li><li>形状网格必须覆盖生产的解码与变长形状，甜点形状的成绩单代表不了部署。</li><li>数值验收与时间测量同权：容差按 dtype 与归约顺序定，分级执行。</li><li>内核层报时间，系统层做 Amdahl 折算，两层不混。</li><li>出处：Williams et al., <em>Roofline</em>, CACM 2009；据 CUDA events 与 nsight 文档口径整理。</li></ul>',5))])}const f=n(m,[["render",p]]);export{_ as __pageData,f as default};
